input.source:
fn count_greater(xs: List[Int], val: Int) -> Int
  requires true
  ensures result >= 0 and result <= len(xs)
  effects pure
  example count_greater([1, 2, 3], 2) == 1
  example count_greater([1, 2, 3], 5) == 0
  example count_greater([], 5) == 0
{
  match xs {
    [] => 0
    [h, ..t] => if h > val then 1 + count_greater(t, val) else count_greater(t, val)
  }
}

fn is_second(xs: List[Int], candidate: Option[Int]) -> Bool
  requires distinct(xs)
  ensures (match candidate {
    None => result == (len(xs) < 2)
    Some(x) => result == (contains(xs, x) and count_greater(xs, x) == 1)
  })
  effects pure
  example is_second([], None) == true
  example is_second([4], None) == true
  example is_second([3, 9, 1], Some(3)) == true
  example is_second([3, 9, 1], Some(9)) == false
{
  match candidate {
    None => len(xs) < 2
    Some(x) => contains(xs, x) and count_greater(xs, x) == 1
  }
}

fn helper_with_full_list(full_xs: List[Int], xs: List[Int], max1: Option[Int], max2: Option[Int]) -> Option[Int]
  requires distinct(full_xs)
  ensures is_second(full_xs, result)
  effects pure
{
  match xs {
    [] => max2
    [h, ..t] => match max1 {
      None => helper_with_full_list(full_xs, t, Some(h), None)
      Some(m1) => if h > m1 then
        helper_with_full_list(full_xs, t, Some(h), Some(m1))
      else
        helper_with_full_list(full_xs, t, Some(m1), max2)
    }
  }
}

fn second_largest(xs: List[Int]) -> Option[Int]
  requires distinct(xs)
  ensures is_second(xs, result)
  effects pure
  example second_largest([3, 9, 1]) == Some(3)
  example second_largest([4]) == None
  example second_largest([]) == None
  example second_largest([1, 2]) == Some(1)
{
  helper_with_full_list(xs, xs, None, None)
}

