fn second_largest(xs: List[Int]) -> Option[Int]
  requires distinct(xs)
  ensures is_second(xs, result)
  effects pure
  example (second_largest([3, 9, 1]) == Some(3))
  example (second_largest([4]) == None)
  example (second_largest([]) == None)
  example (second_largest([5, 2]) == Some(2))
  example (second_largest([1, 2, 3, 4]) == Some(3))
{
  match xs {
    [] => None
    [_] => None
    [a, b] => if a > b then Some(b) else Some(a)
    [h, ..t] => match second_largest(t) {
      None => None
      Some(s) => if h > max_in_list(t) then Some(max_in_list(t)) else Some(s)
    }
  }
}

fn max_in_list(xs: List[Int]) -> Int
  requires distinct(xs) and len(xs) > 0
  ensures result >= 0
  effects pure
  example max_in_list([3, 9, 1]) == 9
  example max_in_list([4]) == 4
{
  match xs {
    [] => 0
    [h] => h
    [h, ..t] => if h > max_in_list(t) then h else max_in_list(t)
  }
}

