fn second_largest(xs: List[Int]) -> Option[Int]
  requires distinct(xs)
  ensures is_second(xs, result)
  effects pure
  example (second_largest([3, 9, 1]) == Some(3))
  example (second_largest([4]) == None)
  example (second_largest([]) == None)
  example (second_largest([5, 2]) == Some(2))
  example (second_largest([1, 2, 3, 4]) == Some(3))
{
  match xs {
    [] => None
    [_] => None
    _ => find_second_aux(xs, None, None)
  }
}

fn find_second_aux(xs: List[Int], max1: Option[Int], max2: Option[Int]) -> Option[Int]
  requires distinct(xs)
  ensures result == None or result == max2
  effects pure
{
  match xs {
    [] => max2
    [h, ..t] => match max1 {
      None => find_second_aux(t, Some(h), None)
      Some(m1) => if h > m1 then
        find_second_aux(t, Some(h), Some(m1))
      else
        match max2 {
          None => find_second_aux(t, Some(m1), Some(h))
          Some(m2) => if h > m2 then
            find_second_aux(t, Some(m1), Some(h))
          else
            find_second_aux(t, Some(m1), Some(m2))
        }
    }
  }
}

